from pathlib import Path
import json,os
os.environ.setdefault("MPLCONFIGDIR","/tmp/race-quest-patch4-mpl")
os.environ.setdefault("XDG_CACHE_HOME","/tmp/race-quest-patch4-cache")
D=Path(__file__).resolve().parents[1];r=json.loads((D/'simulation-results.json').read_text());p=json.loads((D/'personality-tests.json').read_text())
lines=['# Pengukuran perilaku AI — PATCH 3 vs PATCH 4','',f"{r['paired_races']} balapan engine berpasangan: 12 seed × 3 stage × 3 kesulitan × 2 versi. Tambahan {r['standalone_cases']} kasus penyelesaian AI. Langkah simulasi 0,05 detik. Pembalap referensi memakai controller yang sama, tidak memakai item, menjawab 4/5 soal dengan benar. Ini benchmark deterministik, bukan win-rate siswa atau FPS perangkat.",'','| Versi | Kesulitan | Posisi rata-rata pemain referensi | Menang referensi | Kontak rintangan / balapan (4 AI) | Buff dipakai / AI-menit | Hit pemain / 36 balapan |','|---|---|---:|---:|---:|---:|---:|']
for s in r['summary']:
 lines.append(f"| PATCH {s['version']} | {dict(easy='Santai',normal='Sedang',hard='Menantang')[s['difficulty']]} | {s['mean_player_position']:.2f} | {s['player_win_rate']*100:.1f}% | {s['mean_obstacle_contacts_per_race']:.2f} | {s['ai_buff_uses_per_ai_minute']:.2f} | {s['player_hits']} |")
lines+=['','Baseline hanya Gelembung/Oli; PATCH 4 memakai sembilan buff secara kondisional. Kontak rintangan dihitung dari lintasan dan posisi, karena baseline belum memberi penalti collision rintangan pada AI. Counter kontak bukan jumlah damage yang setara pada dua versi. Hit di tabel adalah collision proyektil/oli primer; pantulan tidak dihitung sebagai proyektil tambahan.','', '## Distribusi penggunaan alami', '', '| Kesulitan | Turbo | Perisai | Magnet | Gelembung | Oli | Pantul | Nitro | Grip | Radar |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for s in r['summary']:
 if s['version']==4:lines.append('| '+s['difficulty']+' | '+' | '.join(str(s['uses'].get(k,0))for k in ['turbo','shield','magnet','bubble','oil','reflect','nitro','grip','radar'])+' |')
lines+=['','Setiap baris mencakup 36 balapan × 4 AI. Nitro dihitung per charge yang dipakai. Santai tidak mendapat Gelembung/Oli; Perisai/Pantul dapat tersimpan tetapi tidak perlu dipakai jika tidak ada ancaman. Menyimpan item tanpa menggunakannya bukan kegagalan otomatis.','', '## Penyelesaian dan deadlock', '', '| Kesulitan | Kasus | Rata-rata waktu finis AI | Semua finis | Stall maksimum |','|---|---:|---:|---|---:|']
for c in r['completion']:lines.append(f"| {c['difficulty']} | {c['cases']} | {c['mean_ai_finish_seconds']:.2f} dtk | Ya | {c['max_stall_seconds']:.2f} dtk |")
lines+=['','Harness penyelesaian melanjutkan AI secara terpisah dengan mobil referensi 19 m/s. Harness ini tidak memutar ulang collision item penuh, sehingga menguji kelangsungan gerak/finis, bukan akurasi serangan. Balapan berpasangan di tabel pertama menjalankan collision engine sebenarnya. Stall maksimum pada balapan PATCH 4 dengan collision penuh: '+str(max(x['max_stall_seconds'] for x in r['rows'] if x['version']==4))+' dtk. Jeda quiz tidak dihitung sebagai stall.','', '## Kepribadian pada kesempatan serangan yang identik','','2.000 kesempatan identik per baris, satu item Gelembung, target sah pada posisi yang sama. Persentase adalah pemilihan aksi; target tetap divalidasi ulang sebelum ditembakkan. Ini memisahkan pengaruh kepribadian dari posisi start dan kesempatan berbeda dalam balapan.','','| Kesulitan | Kepribadian | Peluang konfigurasi | Terukur |','|---|---|---:|---:|']
for x in p['cases']:lines.append(f"| {x['difficulty']} | {x['personality']} | {x['configured_probability']*100:.1f}% | {x['empirical_selection_rate']*100:.1f}% |")
lines+=['','Pertahanan pada ancaman identik ETA 1,26 dtk: Defensif dan Seimbang memilih Perisai lebih awal; Agresif dan Berisiko belum menghabiskan Perisai pada jarak itu. Pada ancaman lebih dekat semua dapat bertahan. Peluang di atas bukan peluang mengenai siswa.','', '## Evaluasi yang dibatasi bukti','','Uji pertama menunjukkan kontak rintangan Sedang 5,50 per balapan, lebih buruk daripada baseline 4,00. Kalibrasi memperpanjang jangkauan sensor lokal sesuai waktu reaksi; hasil akhir 3,92. Menantang turun dari 3,56 menjadi 2,47. Santai masih lebih sering menyentuh rintangan (5,28 dibanding 4,64); kemampuan adaptasinya memang rendah dan tidak mengirim serangan. Tidak mengklaim semua perilaku lebih baik pada setiap seed.','','Kecerdasan yang diuji mencakup pemilihan target pemain/AI, pembatalan target setelah windup, pertahanan terhadap proyektil, peluang menghindar dan jalur menyalip, sensor Radar yang terbatas, penggunaan item sesuai konteks, serta pasokan/cooldown terbatas. Pace dasar 16,5 / 21,9 / 22,6 dipertahankan. Penyesuaian pace menurut jarak pemain dihapus; AI dibatasi 23 m/s tanpa boost, 31 m/s dengan boost. Gerak longitudinal selalu speed × dt, tanpa teleport.','','Data mentah, seed, penggunaan tiap aktor dan tiap balapan berada dalam `simulation-results.json`. Tidak ada pengujian siswa SMP, HP fisik, atau klaim signifikansi statistik/FPS.']
(D/'BEHAVIOR-REPORT.md').write_text('\n'.join(lines)+'\n')
try:
 import matplotlib
 matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 plt.rcParams.update({'font.size':10});fig,ax=plt.subplots(1,2,figsize=(10,3.5),layout='constrained');labels=['Santai','Sedang','Menantang'];xs=list(range(3))
 for version,color,dx in [(3,'#798da7',-.18),(4,'#207eab',.18)]:
  group=[x for x in r['summary'] if x['version']==version];ax[0].bar([i+dx for i in xs],[x['mean_obstacle_contacts_per_race'] for x in group],width=.34,label='PATCH '+str(version),color=color)
 ax[0].set_xticks(xs,labels);ax[0].set_ylabel('Kontak / balapan (4 AI)');ax[0].set_title('Kontak rintangan pada balapan referensi');ax[0].legend()
 ax[1].bar(xs,[x['mean_ai_finish_seconds'] for x in r['completion']],color=['#72b49d','#4897ae','#565fa3']);ax[1].set_xticks(xs,labels);ax[1].set_ylabel('Detik simulasi');ax[1].set_title('Waktu finis AI: harness penyelesaian')
 fig.savefig(D/'balance-chart.svg');plt.close(fig)
 plot=D/'balance-chart.svg';plot.write_text('\n'.join(line.rstrip() for line in plot.read_text().splitlines())+'\n')
except ImportError:pass
print('Behavior report written')
